$$('[data-rank]').forEach(b=>b.onclick=()=>{$$('[data-rank]').forEach(x=>x.classList.toggle('active',x===b));rankings(b.dataset.rank)});
$('#invite').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+location.pathname+'#crew');toast('Ссылка на прототип скопирована')}catch{modal(`<h2>Собери свою стаю.</h2><p>Скопируй ссылку на прототип:</p><input id="shareurl" aria-label="Ссылка" readonly style="width:100%;padding:12px;border:1px solid #dde4e6;border-radius:6px">`);$('#shareurl').value=location.origin+location.pathname+'#crew';$('#shareurl').select()}};
$('#export').onclick=()=>{if(!history.length){toast('Сначала сохрани хотя бы один демо-заезд');return}const blob=new Blob([JSON.stringify({app:'SnowWow',demo:true,sessions:history},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='SnowWow_demo_season.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Демо-сезон экспортирован')};
renderCards();renderHistory();rankings('vertical');updatePackage();updateSession();go(location.hash.slice(1)||'explore');
